#include <cstdint>
#include <optional>
#include <vector>

struct Enemy { int health; };
struct Handle { std::uint32_t index; std::uint32_t generation; };

class EnemyPool
{
public:
    explicit EnemyPool(std::size_t slotCount) : m_slots(slotCount)
    {
        // Every slot starts on the free list: slot i's next free is i + 1.
        for (std::size_t i{ 0 }; i < slotCount; ++i) m_slots[i].nextFree = static_cast<std::int64_t>(i + 1 < slotCount ? i + 1 : -1);
        m_freeHead = slotCount > 0 ? 0 : -1;
    }

    std::optional<Handle> create(const Enemy& enemy)
    {
        if (m_freeHead < 0) return std::nullopt;
        const auto index{ static_cast<std::size_t>(m_freeHead) };
        Slot& s{ m_slots[index] };
        m_freeHead = s.nextFree;
        s.enemy = enemy;
        s.used = true;
        ++m_alive;
        return Handle{ static_cast<std::uint32_t>(index), s.generation };
    }

    Enemy* get(Handle h)
    {
        Slot* s{ slotFor(h) };
        return s ? &s->enemy : nullptr;
    }

    bool destroy(Handle h)
    {
        Slot* s{ slotFor(h) };
        if (!s) return false;
        s->used = false;
        ++s->generation;                       // every existing handle to this slot is now stale
        s->nextFree = m_freeHead;
        m_freeHead = static_cast<std::int64_t>(h.index);
        --m_alive;
        return true;
    }

    std::size_t alive() const { return m_alive; }

private:
    struct Slot { Enemy enemy{}; std::uint32_t generation{ 0 }; bool used{ false }; std::int64_t nextFree{ -1 }; };

    Slot* slotFor(Handle h)
    {
        if (h.index >= m_slots.size()) return nullptr;
        Slot& s{ m_slots[h.index] };
        return (s.used && s.generation == h.generation) ? &s : nullptr;
    }

    std::vector<Slot> m_slots;
    std::int64_t m_freeHead{ -1 };
    std::size_t m_alive{ 0 };
};

unitTests:
TEST("create and get") { EnemyPool p{ 4 }; const auto h{ p.create(Enemy{ 30 }) }; CHECK(h.has_value()); CHECK(p.get(*h) != nullptr); CHECK_EQ(p.get(*h)->health, 30); CHECK_EQ(p.alive(), std::size_t{ 1 }); }
TEST("changes through get stick") { EnemyPool p{ 2 }; const auto h{ *p.create(Enemy{ 30 }) }; p.get(h)->health -= 10; CHECK_EQ(p.get(h)->health, 20); }
TEST("full pool") { EnemyPool p{ 2 }; p.create(Enemy{ 1 }); p.create(Enemy{ 2 }); CHECK(!p.create(Enemy{ 3 }).has_value()); }
TEST("destroy makes the handle stale") { EnemyPool p{ 2 }; const auto h{ *p.create(Enemy{ 5 }) }; CHECK(p.destroy(h)); CHECK(p.get(h) == nullptr); CHECK(!p.destroy(h)); CHECK_EQ(p.alive(), std::size_t{ 0 }); }
TEST("a reused slot does not answer old handles")
{
    EnemyPool p{ 1 };
    const auto goblin{ *p.create(Enemy{ 10 }) };
    p.destroy(goblin);
    const auto bat{ *p.create(Enemy{ 99 }) };
    CHECK_EQ(bat.index, goblin.index);          // the only slot was reused...
    CHECK(bat.generation != goblin.generation); // ...with a new generation
    CHECK(p.get(goblin) == nullptr);
    CHECK_EQ(p.get(bat)->health, 99);
}
TEST("freed slots are reused") { EnemyPool p{ 2 }; auto a{ *p.create(Enemy{ 1 }) }; p.create(Enemy{ 2 }); p.destroy(a); CHECK(p.create(Enemy{ 3 }).has_value()); CHECK_EQ(p.alive(), std::size_t{ 2 }); }
TEST("nonsense handles") { EnemyPool p{ 2 }; CHECK(p.get(Handle{ 7, 0 }) == nullptr); CHECK(!p.destroy(Handle{ 7, 0 })); CHECK(p.get(Handle{ 0, 0 }) == nullptr); }
TEST("an empty pool") { EnemyPool p{ 0 }; CHECK(!p.create(Enemy{ 1 }).has_value()); }

